    private function mapper(array $row): Template
    {
        $this->logDebug("Mapping from sql to entity for Template");
        $span = $this->startSpan("Mapping from sql to entity for Template");
        try {
            $uid = $row['uid'] ?? null;
            if (null === $uid) {
                throw ConstraintException::ofError('not-null', ['uid'], [null]);
            }
            $code = $row['code'] ?? null;
            if (null === $code) {
                throw ConstraintException::ofError('not-null', ['code'], [null]);
            }
            $tenant = isset($row['tenant']) ? new TenantRef(uid: $row['tenant']) : null;
            $theme = $row['theme'] ?? null;
            // throws validation exception if is null.
            $channel = TemplateChannelVO::fromString($row['channel'] ?? '');
            $enabled = isset($row['enabled']) ? !! $row['enabled'] : null;
            $version = $row['version'] ?? null;
            return new Template(
                uid: $uid,
                code: $code,
                tenant: $tenant,
                theme: $theme,
                channel: $channel,
                enabled: $enabled,
                version: $version,
            );
        } catch (Throwable $ex) {
